 IEnumerator Songs(){int songs=mode=="all-songs"?7:1;for(int song=0;song<songs;song++){m.SetupScreen();m.setup.count=4;m.option=(mode=="hard"?14:mode=="insane"?21:7)+song;m.NormalizeSetup();m.AllBots();for(int i=0;i<4;i++)m.setup.players[i].difficulty=(BowlingDifficulty)Mathf.Min(2,i);Check(m.StartMatch(),"four independent AI dancers start "+m.library.Get(song).title);float began=Time.realtimeSinceStartup;yield return Wait(()=>m.SongTime>8,15);Check(m.Phase==DancePhase.Song&&m.music.isPlaying&&m.PhysicalRoutines>0,"scheduled original song advances the DSP clock and visible input-linked choreography");int sum=0;foreach(var rule in m.Rules)sum+=rule.Score;Check(sum>0,"AI uses note/hold/freestyle inputs through the same timing rules");double clock=m.SongTime;int points=m.Rules[0].Score;m.Pause();clock=m.SongTime;points=m.Rules[0].Score;yield return new WaitForSecondsRealtime(.25f);Check(m.Paused&&Math.Abs(m.SongTime-clock)<.1&&m.Rules[0].Score==points&&!m.music.isPlaying,"pause preserves song time and score and suspends music");m.Resume();yield return new WaitForSecondsRealtime(1.4f);Check(m.SongTime>=clock&&m.SongTime<clock+1,"resume count-in preserves audio/chart synchronization");if(song==0){foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080),new Vector2Int(1440,1080),new Vector2Int(2560,1080)}){SportsControlledCapture.Save(m,size.x,size.y,folder+"/stage-"+size.x+"x"+size.y+".png");yield return null;}}
 if(mode=="visual"){m.SetupScreen();yield break;}yield return Wait(()=>m.Finished,(float)m.Song.duration+20);Check(m.Finished,"complete original "+m.Song.genre+" song reaches final results without score injection");bool valid=true;for(int i=0;i<4;i++){valid&=m.total[i]==m.Rules[i].Score&&m.Rules[i].Resolved==m.Rules[i].Count;report.AppendLine("SONG="+m.Song.title+" participant="+i+" score="+m.total[i]+" perfect="+m.Rules[i].Perfect+" great="+m.Rules[i].Great+" good="+m.Rules[i].Good+" miss="+m.Rules[i].Miss+" maxCombo="+m.Rules[i].MaximumCombo);}Check(valid,"each chart note resolves once and result equals authoritative song score");report.AppendLine("SONG_REAL_SECONDS="+(Time.realtimeSinceStartup-began).ToString("F2"));}}
 static Vector2 MaskVector(int mask)=>new Vector2(((mask&8)!=0?1:0)-((mask&1)!=0?1:0),((mask&4)!=0?1:0)-((mask&2)!=0?1:0));
 IEnumerator InputCheck(){m.SetupScreen();m.setup.count=2;m.option=0;m.NormalizeSetup();m.AllBots();pad=InputSystem.AddDevice<Gamepad>();m.setup.players[0].source=BowlingSource.LeftStick;m.setup.players[1].source=BowlingSource.RightStick;m.setup.players[0].pad=m.setup.players[1].pad=pad;Check(m.ValidateSources(out _),"two exclusive stick owners share one injected pad");Check(m.StartMatch(),"shared-stick human configuration starts");var first=m.Rules[0].Note(0);yield return Wait(()=>m.SongTime>=first.time-.02,8);InputSystem.QueueStateEvent(pad,new GamepadState{leftStick=MaskVector(first.mask)});yield return new WaitForSecondsRealtime(.25f);Check(m.Rules[0].Score>0&&m.Rules[1].Score==0,"injected left stick scores only its owned chart");InputSystem.QueueStateEvent(pad,new GamepadState());yield return null;m.Pause();double at=m.SongTime;InputSystem.RemoveDevice(pad);yield return null;replacement=InputSystem.AddDevice<Gamepad>();Check(m.Assign(0,replacement)&&m.Assign(1,replacement),"explicit replacement preserves left/right ownership without restarting");m.Resume();yield return new WaitForSecondsRealtime(1.4f);var note=m.Rules[1].Note(2);yield return Wait(()=>m.SongTime>=note.time-.02,10);int old=m.Rules[1].Score;InputSystem.QueueStateEvent(replacement,new GamepadState{rightStick=MaskVector(note.mask)});yield return new WaitForSecondsRealtime(.23f);Check(m.Rules[1].Score>old,"reconnected right-stick input map follows the replacement controller");InputSystem.QueueStateEvent(replacement,new GamepadState());yield return null;m.SetupScreen();}
 IEnumerator CalibrationCheck(){m.SetupScreen();m.setup.count=1;m.option=0;m.NormalizeSetup();m.AllBots();pad=InputSystem.AddDevice<Gamepad>();m.setup.players[0].source=BowlingSource.LeftStick;m.setup.players[0].pad=pad;m.ExtraAction("dance-calibrate");Check(m.Calibrating,"actual setup calibration uses the assigned input source and scheduled audio pulse");for(int tap=0;tap<12;tap++){double at=m.CalibrationReferenceDSP+tap+.075;yield return Wait(()=>AudioSettings.dspTime>=at,2);InputSystem.QueueStateEvent(pad,new GamepadState{leftStick=Vector2.left});yield return new WaitForSecondsRealtime(.12f);InputSystem.QueueStateEvent(pad,new GamepadState());yield return null;}Check(!m.Calibrating&&m.CalibrationSamples==12&&m.CalibrationMs>60&&m.CalibrationMs<105,"twelve real injected taps measure the intentional 75ms input delay (observed "+m.CalibrationMs.ToString("F1")+"ms)");Check(Mathf.Abs(SportsPrefs.GetFloat("TruckDanceOff.Presentation.v1.CalibrationMs",-999)-m.CalibrationMs)<.01f,"measured timing offset is persisted through shared scoped preferences");m.ExtraAction("dance-reset-calibration");Check(m.CalibrationMs==0&&!m.calibrationAudio.isPlaying,"calibration stops and can reset without starting a match");}
 IEnumerator MixedCheck(){m.SetupScreen();m.setup.count=4;m.option=0;m.NormalizeSetup();m.AllBots();keyboard=InputSystem.AddDevice<Keyboard>();whole=InputSystem.AddDevice<Gamepad>();pad=InputSystem.AddDevice<Gamepad>();m.setup.players[0].source=BowlingSource.Keyboard;m.setup.players[1].source=BowlingSource.WholeController;m.setup.players[1].pad=whole;m.setup.players[2].source=BowlingSource.LeftStick;m.setup.players[3].source=BowlingSource.RightStick;m.setup.players[2].pad=m.setup.players[3].pad=pad;Check(m.ValidateSources(out _),"four independent charts accept keyboard, whole controller and two owned sticks");m.setup.players[2].pad=whole;Check(!m.ValidateSources(out _),"whole-controller ownership still rejects another participant's overlapping stick");m.setup.players[2].pad=pad;Check(m.StartMatch(),"four-human mixed injected source configuration starts");double at=m.Rules[0].Note(0).time;yield return Wait(()=>m.SongTime>=at-.02,8);InputSystem.QueueStateEvent(keyboard,new KeyboardState(m.setup.players[0].left));InputSystem.QueueStateEvent(whole,new GamepadState().WithButton(GamepadButton.West));InputSystem.QueueStateEvent(pad,new GamepadState{leftStick=Vector2.left,rightStick=Vector2.left});yield return new WaitForSecondsRealtime(.24f);bool all=true;for(int i=0;i<4;i++)all&=m.Rules[i].Score>0;Check(all,"each of four actual owned InputAction maps scores its own first note");InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.QueueStateEvent(whole,new GamepadState());InputSystem.QueueStateEvent(pad,new GamepadState());yield return null;int[] old=new int[4];for(int i=0;i<4;i++)old[i]=m.Rules[i].Score;var next=m.Rules[2].Note(1);yield return Wait(()=>m.SongTime>=next.time-.02,8);InputSystem.QueueStateEvent(pad,new GamepadState{leftStick=MaskVector(next.mask)});yield return new WaitForSecondsRealtime(.24f);Check(m.Rules[2].Score>old[2]&&m.Rules[0].Score==old[0]&&m.Rules[1].Score==old[1]&&m.Rules[3].Score==old[3],"a later left-stick event cannot score any