 IEnumerator ShowCheck(){m.SetupScreen();m.setup.count=4;m.option=7;m.NormalizeSetup();m.AllBots();if(m.Format==0)m.ExtraAction("dance-format");Check(m.Format==1&&m.StartMatch(),"three-song four-AI show starts without human confirmation");int observed=0;int[] expected=new int[4];float deadline=Time.realtimeSinceStartup+245;while(!m.Finished&&Time.realtimeSinceStartup<deadline){if(m.Phase==DancePhase.RoundResult&&m.Round>observed){observed=m.Round;bool same=true;for(int i=0;i<4;i++){expected[i]+=m.Rules[i].Score;same&=expected[i]==m.total[i];}Check(same,"show round "+observed+" banks exactly the actual chart scores once");}yield return null;}bool valid=m.Finished&&m.Round==3&&observed==3;for(int i=0;i<4;i++)valid&=expected[i]==m.total[i];Check(valid,"three complete DSP songs advance automatically to correct cumulative final standings");m.SetupScreen();m.ExtraAction("dance-format");}
